SELECT DISTINCT m.* FROM sys_menu m INNER JOIN sys_role_menu rm ON m.menu_id = rm.menu_id WHERE rm.role_id IN
#{roleId}
AND m.del_flag = '0' AND m.status = '0' ORDER BY m.parent_id, m.sort_order

mapper.update:
UPDATE sys_menu
SET menu_name = #{menuName}, parent_id = #{parentId}, path = #{path},
    component = #{component}, perms = #{perms}, icon = #{icon},
    sort_order = #{sortOrder}, menu_type = #{menuType}, status = #{status},
    visible = #{visible}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}
WHERE menu_id = #{menuId}
